#include <stdio.h>
#include <string.h>
#include <curl/mprintf.h>

int main() {
    // Small buffer - 16 bytes
    char buffer[16];
    memset(buffer, 0, sizeof(buffer));

    // Long format string that will produce output much larger than 16 bytes
    // Using %s with a long string argument
    char long_string[200];
    memset(long_string, 'A', sizeof(long_string) - 1);
    long_string[sizeof(long_string) - 1] = '\0';

    printf("Buffer size: %zu bytes\n", sizeof(buffer));
    printf("Input string length: %zu bytes\n", strlen(long_string));
    printf("Calling curl_msprintf...\n");

    // This should overflow the buffer
    int result = curl_msprintf(buffer, "%s", long_string);

    printf("Result: %d\n", result);
    printf("Buffer content (first 32 bytes): ");
    for (int i = 0; i < 32; i++) {
        if (buffer[i] == 0) printf("\\0");
        else if (buffer[i] >= 32 && buffer[i] < 127) printf("%c", buffer[i]);
        else printf(".");
    }
    printf("\n");

    return 0;
}

