/*
 * PoC to test the buffer alignment issue in Curl_ipv4_resolve_r on AmigaOS.
 * This simulates the pointer arithmetic issue by checking if the data buffer
 * pointer is properly aligned for the expected data structures.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdalign.h>

#define CURL_HOSTENT_SIZE 9000

/* Simulated hostent structure - on AmigaOS this might have different alignment */
struct hostent {
    char    *h_name;        /* official name of host */
    char   **h_aliases;     /* alias list */
    int     h_addrtype;     /* host address type */
    int     h_length;       /* length of address */
    char   **h_addr_list;   /* list of addresses */
};

/* Test if the pointer arithmetic accounts for alignment */
int main(void) {
    void *buf = calloc(1, CURL_HOSTENT_SIZE);
    if (!buf) {
        fprintf(stderr, "Failed to allocate buffer\n");
        return 1;
    }

    struct hostent *h = (struct hostent *)buf;
    char *data_buf = (char *)buf + sizeof(struct hostent);
    size_t data_size = CURL_HOSTENT_SIZE - sizeof(struct hostent);

    printf("Buffer size: %d\n", CURL_HOSTENT_SIZE);
    printf("sizeof(struct hostent): %zu\n", sizeof(struct hostent));
    printf("Data buffer pointer: %p\n", (void *)data_buf);
    printf("Data buffer size: %zu\n", data_size);
    printf("Alignment of data_buf: %zu\n", (uintptr_t)data_buf % alignof(max_align_t));
    printf("Alignment requirement for max_align_t: %zu\n", alignof(max_align_t));

    /* Check if data_buf is properly aligned for typical data structures */
    if ((uintptr_t)data_buf % alignof(max_align_t) != 0) {
        printf("WARNING: data_buf is NOT properly aligned for max_align_t!\n");
        printf("This could cause issues if gethostbyname_r expects aligned data.\n");
    } else {
        printf("data_buf is properly aligned.\n");
    }

    /* Check if there's enough space for typical DNS response data */
    /* A typical DNS response might need space for:
     * - canonical name (up to 255 bytes)
     * - alias pointers and strings
     * - address list (multiple IPv4 addresses, 4 bytes each)
     */
    size_t min_needed = 256 + 16 * 8 + 32 * 4;  /* rough estimate */
    printf("Estimated minimum needed for DNS data: %zu\n", min_needed);
