#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "curl/curl.h"

/* Test the cookie API directly to trigger the reported code paths */

int main() {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to init curl\n");
        return 1;
    }

    /* Test 1: Multiple cookie replacements with same name/domain/path */
    printf("=== Test 1: Multiple cookie replacements ===\n");

    /* First add a cookie via cookie file */
    FILE *f = fopen("/tmp/cookies_test1.txt", "w");
    if (f) {
        fprintf(f, "# Netscape HTTP Cookie File\n");
        fprintf(f, "example.com\tTRUE\t/\tFALSE\t0\ttestcookie\tvalue1\n");
        fclose(f);
    }

    curl_easy_setopt(curl, CURLOPT_COOKIEFILE, "/tmp/cookies_test1.txt");
    curl_easy_setopt(curl, CURLOPT_COOKIEJAR, "/tmp/cookies_test1_out.txt");
    curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/");
    curl_easy_setopt(curl, CURLOPT_NOBODY, 1L);
    curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);
    curl_easy_perform(curl);

    /* Now replace the cookie many times via headers */
    for (int i = 0; i < 1000; i++) {
        char header[256];
        snprintf(header, sizeof(header), "Set-Cookie: testcookie=value%d; domain=example.com; path=/", i);
        struct curl_slist *headers = curl_slist_append(NULL, header);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_perform(curl);
        curl_slist_free_all(headers);
    }

    /* Test 2: Cookie file with invalid/malformed cookies that trigger error paths */
    printf("\n=== Test 2: Malformed cookies in file ===\n");

    f = fopen("/tmp/cookies_test2.txt", "w");
    if (f) {
        fprintf(f, "# Netscape HTTP Cookie File\n");
        /* Valid cookie first */
        fprintf(f, "example.com\tTRUE\t/\tFALSE\t0\tvalidcookie\tvalidvalue\n");
        /* Malformed - missing name */
        fprintf(f, "example.com\tTRUE\t/\tFALSE\t0\t\tvalue2\n");
        /* Malformed - missing value */
        fprintf(f, "example.com\tTRUE\t/\tFALSE\t0\tname3\t\n");
        /* Malformed - missing domain */
        fprintf(f, "\tTRUE\t/\tFALSE\t0\tname4\tvalue4\n");
        /* Malformed - missing path */
        fprintf(f, "example.com\tTRUE\t\tFALSE\t0\tname5\tvalue5\n");
        /* Malformed - missing secure flag */
        fprintf(f, "example.com\t\t/\tFALSE\t0\tname6\tvalue6\n");
        /* Malformed - missing expires */
        fprintf(f, "example.com\tTRUE\t/\tFALSE\t\tname7\tvalue7\n");
        /* Malformed - completely empty line */
        fprintf(f, "\n");
        /* Malformed - just tabs */
        fprintf(f, "\t\t\t\t\t\t\n");
        fclose(f);
    }

    CURL *curl2 = curl_easy_init();
    if (curl2) {
        curl_easy_setopt(curl2, CURLOPT_COOKIEFILE, "/tmp/cookies_test2.txt");
        curl_easy_setopt(curl2, CURLOPT_COOKIEJAR, "/tmp/cookies_test2_out.txt");
        curl_easy_setopt(curl2, CURLOPT_URL, "http://example.com/");
        curl_easy_setopt(curl2, CURLOPT_NOBODY, 1L);
        curl_easy_setopt(curl2, CURLOPT_VERBOSE, 1L);
        curl_easy_perform(curl2);
        curl_easy_cleanup(curl2);
    }

    /* Test 3: Test with __Secure- and __Host- prefix cookies that fail validation */
    printf("\n=== Test 3: Prefix validation failures ===\n");

    f = fopen("/tmp/cookies_test3.txt", "w");
    if (f) {
        fprintf(f, "# Netscape HTTP Cookie File\n");
        /* __Secure- prefix but not secure */
        fprintf(f, "example.com\tTRUE\t/\tFALSE\t0\t__Secure-test\tvalue\n");
        /* __Host- prefix but not secure */
        fprintf(f, "example.com\tTRUE\t/\tFALSE\t0\t__Host-test\tvalue\n");
        /* __Host- prefix but has domain */
        fprintf(f, "example.com\tTRUE\t/\tTRUE\t0\t__Host-test2\tvalue\n");
        /* __Host- prefix but path not / */
        fprintf(f, "example.com\tTRUE\t/path\tTRUE\t0\t__Host-test3\tvalue\n");
        fclose(f);
    }

    CURL *curl3 = curl_easy_init();
    if (curl3) {
        curl_easy_setopt(curl3, CURLOPT_COOKIEFILE, "/tmp/cookies_test3.txt");
        curl_easy_setopt(curl3, CURLOPT_COOKIEJAR, "/tmp/cookies_test3_out.txt");
        curl_easy_setopt(curl3, CURLOPT_URL, "http://example.com/");
        curl_easy_setopt(curl3, CURLOPT_NOBODY, 1L);
        curl_easy_setopt(curl3, CURLOPT_VERBOSE, 1L);
        curl_easy_perform(curl3);
        curl_easy_cleanup(curl3);
    }

    /* Test 4: Public suffix domain cookies that should fail */
    printf("\n=== Test 4: Public suffix domain cookies ===\n");

    f = fopen("/tmp/cookies_test4.txt", "w");
    if (f) {
        fprintf(f, "# Netscape HTTP Cookie File\n");
        /* These should fail is_public_suffix check */
        fprintf(f, "com\tTRUE\t/\tFALSE\t0\tpscookie\tvalue\n");
        fprintf(f, "co.uk\tTRUE\t/\tFALSE\t0\tpscookie2\tvalue\n");
        fprintf(f, "github.io\tTRUE\t/\tFALSE\t0\tpscookie3\tvalue\n");
        fclose(f);
    }

    CURL *curl4 = curl_easy_init();
    if (curl4) {
        curl_easy_setopt(curl4, CURLOPT_COOKIEFILE, "/tmp/cookies_test4.txt");
        curl_easy_setopt(curl4, CURLOPT_COOKIEJAR, "/tmp/cookies_test4_out.txt");
        curl_easy_setopt(curl4, CURLOPT_URL, "http://example.com/");
        curl_easy_setopt(curl4, CURLOPT_NOBODY, 1L);
