#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

/* Minimal implementation of curl_maprintf that shows the vulnerability */
char *curl_maprintf(const char *format, ...) {
    va_list ap_save;
    char *s;
    va_start(ap_save, format);

    /* This mimics what curl_mvaprintf does - it uses vsnprintf which calls strlen for %s */
    va_list ap;
    va_copy(ap, ap_save);
    int len = vsnprintf(NULL, 0, format, ap);
    va_end(ap);

    if(len < 0) {
        va_end(ap_save);
        return NULL;
    }

    s = malloc(len + 1);
    if(!s) {
        va_end(ap_save);
        return NULL;
    }

    vsnprintf(s, len + 1, format, ap_save);
    va_end(ap_save);
    return s;
}

int main(void) {
    /* Create non-null-terminated header name and value */
    char name_buf[80];
    char value_buf[80];
    memset(name_buf, 'A', sizeof(name_buf));
    memset(value_buf, 'B', sizeof(value_buf));
    name_buf[79] = 'A';  /* No null terminator */
    value_buf[79] = 'B'; /* No null terminator */

    size_t namelen = 79;
    size_t valuelen = 79;

    printf("Testing curl_maprintf with non-null-terminated strings...\n");
    printf("name buffer at %p, value buffer at %p\n", (void*)name_buf, (void*)value_buf);

    char *result = curl_maprintf("%s:%s", name_buf, value_buf);

    if(result) {
        printf("Result length: %zu\n", strlen(result));
        printf("Result: %s\n", result);
        free(result);
    } else {
        printf("curl_maprintf returned NULL\n");
    }

    return 0;
}

